export const zones = { local: 250, national: 500 };
export function quote(weight, zone = 'local') {
  if (!Number.isFinite(weight) || weight <= 0 || !Object.hasOwn(zones, zone)) throw new Error('Invalid parcel');
  return zones[zone] + Math.floor(weight * 100);
}

