export async function deliver(tasks, retries = 0) {
  const results = []; let attempt = 0;
  for (const task of tasks) {
    while (true) {
      try { results.push(await task()); break; }
      catch (error) { if (attempt++ >= retries) throw error; }
    }
  }
  return results;
}

